SOURCE_INPUTS={'lighthouse': {'asset_id': 'harbor-tapered-lantern-lighthouse-01', 'sha256': 'a107340dd2bde27a7f6ffa84e3da133b4a7fc46a7be34427026ec9cb61488864', 'compressed': ''}, 'dock': {'asset_id': 'harbor-dock-module-01', 'sha256': '69502b87d90f1421f9601a7bc342d32988b764499051d7161c60eca8e134bc8c', 'compressed': ''}}
